    "q": "β-lactoglobulin และ α-lactalbumin เป็นกรดอะมิโนที่พบได้มากในน้ำนมโค ช่วยในการเสริมสร้างภูมิคุ้มกันโรคให้กับผู้บริโภค",
    "answer": false,
