    "q": "วิธีการล้างทำความสะอาดด้วยไอน้ำหรือน้ำร้อนอย่างเหมาะสมต้องใช้อุณหภูมิกี่องศาเซลเซียส",
    "options": [
      "75",
      "65",
      "85",
      "95"
    ],
    "answer": 2,
    "explain": "การล้างทำความสะอาดและฆ่าเชื้ออุปกรณ์รีดนม ถังนม และระบบท่อด้วยน้ำร้อนหรือไอน้ำ ต้องใช้ความร้อนที่สูงพอและนานพอจึงจะทำลายจุลินทรีย์ที่ตกค้างและฟิล์มไขมัน-โปรตีนในระบบท่อได้ อุณหภูมิที่กำหนดคือ 85 องศาเซลเซียส ข้อที่คนมักเลือกผิดคือ 65 และ 75 องศาเซลเซียส เพราะจำสลับกับอุณหภูมิพาสเจอไรซ์น้ำนม (LTLT 63 องศาฯ, HTST 72 องศาฯ) ซึ่งเป็นการฆ่าเชื้อ 'ในน้ำนม' ไม่ใช่การ sanitize 'อุปกรณ์' ส่วน 95 องศาเซลเซียส สูงเกินความจำเป็นและสิ้นเปลืองพลังงานโดยไม่เพิ่มประสิทธิภาพอย่างมีนัยสำคัญ",
