    "q": "วิธีที่ดีที่สุดในการแก้ไขปัญหา Mycotoxin ในวัตถุดิบอาหารสัตว์คือ การนำไปใช้กับสัตว์ที่มีความไวต่อ Mycotoxin น้อยกว่า เช่นสัตว์ที่โตเต็มที่แล้ว",
    "answer": false,
    "explain": "การแก้ปัญหา mycotoxin ที่ถูกต้องคือการป้องกันและตัดต้นทาง ได้แก่ คัดเลือกและปฏิเสธวัตถุดิบที่ปนเปื้อน ควบคุมความชื้นและการเก็บรักษาไม่ให้เชื้อราเจริญ สุ่มตรวจระดับสารพิษ และถ้าจำเป็นจึงใช้สารดูดซับ (toxin binder) ร่วมด้วย การเอาวัตถุดิบที่ปนเปื้อนไปให้สัตว์ที่ 'ทนกว่า' เป็นการผลักความเสี่ยงไม่ใช่การแก้ปัญหา เพราะสัตว์โตเต็มวัยก็ยังถูกกดภูมิคุ้มกันและให้ผลผลิตลดลง และในโคนม aflatoxin B1 จะถูกขับออกมาเป็น aflatoxin M1 ในน้ำนม ทำให้สารพิษไปถึงผู้บริโภคโดยตรง",
