    "year": 5,
    "type": "mcq",
    "q": "สารฆ่าเชื้อกลุ่มใดต่อไปนี้ออกฤทธิ์โดยการออกซิไดซ์หมู่ไทออลทำให้หน้าที่และโครงสร้างของจุลินทรีย์เปลี่ยนแปลง",
    "options": [
      "Chlorhexidine",
      "Oxidizing agents",
      "Halogen compounds",
      "Phenolic compounds"
    ],
    "answer": 2,
    "explain": "คำตอบคือ Halogen compounds (คลอรีน ไอโอดีน และสารประกอบของทั้งสอง) ซึ่งออกฤทธิ์เป็นตัวออกซิไดซ์หมู่ที่มี C, S และ N โดยเฉพาะการออกซิไดซ์หมู่ไทออล (-SH) และทำลายพันธะ disulphide ของโปรตีน ทำให้โครงสร้างและหน้าที่ของโปรตีนเปลี่ยน รบกวนเมแทบอลิซึมของจุลินทรีย์จนตาย เป็นกลุ่มที่ใช้มากที่สุดในการล้างอุปกรณ์รีดนมและถังนม ตัวลวงที่หลอกได้ง่ายที่สุดคือ Oxidizing agents เพราะโจทย์มีคำว่า 'ออกซิไดซ์' ตรงตัว แต่กลุ่ม oxidizing agents เช่น ไฮโดรเจนเปอร์ออกไซด์และ peracetic acid ออกฤทธิ์ผ่านอนุมูลอิสระทำลายหลายองค์ประกอบของเซลล์ ไม่ได้เจาะจงที่หมู่ไทออลแบบฮาโลเจน ส่วน Chlorhexidine และ Phenolic compounds ออกฤทธิ์ที่เยื่อหุ้มเซลล์และทำให้โปรตีนเสียสภาพ ไม่ใช่การออกซิไดซ์",
