    "q": "สารประกอบพวก phenol, cresol และ xylenol เป็นสารประกอบที่ใช้กันอย่างแพร่หลายภายในโรงพยาบาลและโรงงาน สารประกอบเหล่านี้มีบทบาทในการฆ่าเชื้อจุลินทรีย์อย่างไร",
