    "explain": "สารกลุ่ม phenolics (phenol, cresol, xylenol) ฆ่าเชื้อโดยเข้าไปทำลายเยื่อหุ้มเซลล์/พันธะที่ยึดโครงสร้างเซลล์ไว้ แล้วทำให้โปรตีนภายในเซลล์เสียสภาพ (protein denaturation) จึงออกฤทธิ์ได้แม้มีสารอินทรีย์ปนเปื้อน และนิยมใช้ในโรงพยาบาล/โรงงาน ตัวล่อที่คนตอบผิดบ่อยคือ 'ลดแรงตึงผิวของ cell membrane' ซึ่งเป็นกลไกของสารลดแรงตึงผิว (surface active agents เช่น quaternary ammonium, สบู่) ส่วนการเป็น oxidizing agent รุนแรงคือกลุ่มคลอรีน/ไอโอดีน/เปอร์ออกไซด์ และการตกตะกอนโปรตีนด้วยปฏิกิริยา alkylation คือกลุ่ม aldehyde (formaldehyde, glutaraldehyde) จำเป็นหมวด ๆ ไว้จะแยกกลไกของสารฆ่าเชื้อแต่ละกลุ่มได้ทันที",
