    "answer": 0,
    "explain": "องค์ประกอบน้ำนมโคดิบโดยเฉลี่ยคือ น้ำประมาณ 87% และของแข็งทั้งหมด (total solids) ประมาณ 13% ในส่วนของแข็งนั้น เรียงจากมากไปน้อยคือ lactose ประมาณ 4.6-4.9%, fat ประมาณ 3.5-4.0%, protein ประมาณ 3.2-3.5% และ ash หรือ vitamins and minerals ประมาณ 0.7-0.9% ดังนั้นเมื่อถามว่า \"ส่วนประกอบใดพบมากที่สุด\" โดยไม่นับน้ำ คำตอบคือ lactose ซึ่งเป็นไดแซ็กคาไรด์ของ glucose กับ galactose สร้างที่เต้านมโดยเอนไซม์ lactose synthase และเป็นตัวกำหนดปริมาณน้ำนมเพราะดึงน้ำเข้าถุงน้ำนมด้วยแรงออสโมซิส lactose ยังนับรวมอยู่ในค่า SNF (solids-not-fat) ข้อควรระวังคือ ถ้าโจทย์มีตัวเลือก \"น้ำ\" ด้วย คำตอบต้องเป็นน้ำ และคนมักหลงเลือก fat เพราะเป็นค่าที่ถูกใช้กำหนดราคารับซื้อน้ำนมดิบ แต่ปริมาณไขมันน้อยกว่าแลคโตส",
